// Validation is performed again in n8n, never blindly trusting the CSV client.
const body = $input.first().json.body;
if (!body || body.schema_version !== '1.0' || !['csv', 'pdf', 'image'].includes(body.source_type)) {
  throw new Error('Unsupported or missing schema_version/source_type');
}
const r = body.record;
if (!r || typeof r !== 'object' || !/^REC-[a-f0-9]{16}-[0-9]{5}$/.test(r.record_id || '')) {
  throw new Error('Invalid record_id');
}
const norm = value => typeof value === 'string' ? value.trim() : '';
const supplier = norm(r.supplier);
const material = norm(r.material);
if (supplier.length > 255 || material.length > 255) {
  throw new Error('Supplier/material exceeds database length limit');
}
const quantity = (Number.isSafeInteger(r.quantity) && r.quantity > 0) ? r.quantity : null;
const missing = [];
const errors = [];
if (!supplier) missing.push('supplier');
if (!material) missing.push('material');
if (r.quantity === null || r.quantity === undefined || r.quantity === '') {
  missing.push('quantity');
} else if (quantity === null) {
  errors.push('quantity_must_be_positive_integer');
}
const clientErrors = Array.isArray(r.errors) ? r.errors : [];
if (clientErrors.includes('quantity_must_be_positive_integer') &&
    !errors.includes('quantity_must_be_positive_integer')) {
  errors.push('quantity_must_be_positive_integer');
}
const needsReview = body.source_type !== 'csv' ||
  missing.length > 0 || errors.length > 0 ||
  r.status === 'REVIEW_REQUIRED' ||
  (Array.isArray(r.review_reasons) && r.review_reasons.length > 0);
const status = needsReview ? 'REVIEW_REQUIRED' : 'OK';
return [{
  json: {
    record_id: r.record_id,
    supplier: supplier || null,
    material: material || null,
    quantity,
    status,
    missing_fields: missing,
    errors,
    process_step: needsReview ? 'Manual Review' : 'Ready Processing',
    workflow_name: 'Warehouse CSV/PDF n8n Import',
    workflow_version: '2.0'
  }
}];
